 "content": "def transform(grid):
    """Decode a tiled 2-pattern whose occupied cells are themselves tile positions.

    A solid 3-band hides a row or column of tile copies. The seed tile's 2-pattern
    describes which positions in the tile lattice are occupied. Clear the divider,
    restore each occupied tile, and mark its lattice coordinate within that tile.
    """
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    if not h or not w:
        return g

    def runs(indices):
        out = []
        for x in indices:
            if not out or x != out[-1][-1] + 1:
                out.append([x])
            else:
                out[-1].append(x)
        return out

    row_band = [r for r in range(h) if all(v == 3 for v in g[r])]
    col_band = [c for c in range(w) if all(g[r][c] == 3 for r in range(h))]
    if row_band:
        bands, horizontal = runs(row_band), True
        band = max(bands, key=len)
        d = len(band)
    elif col_band:
        bands, horizontal = runs(col_band), False
        band = max(bands, key=len)
        d = len(band)
    else:
        return g

    # Tile blocks use a one-cell zero gutter, so their lattice pitch is d+1.
    pitch = d + 1
    row_origins = list(range(0, h - d + 1, pitch))
    col_origins = list(range(0, w - d + 1, pitch))
    candidates = []
    for r0 in row_origins:
        for c0 in col_origins:
            if any(r0 <= r < r0 + d for r in row_band) or any(c0 <= c < c0 + d for c in col_band):
                continue
            tile = [g[r0 + r][c0:c0 + d] for r in range(d)]
            if all(v in (0, 2) for row in tile for v in row):
                count = sum(v == 2 for row in tile for v in row)
                if count:
                    candidates.append((count, tuple(tuple(row) for row in tile)))
    if not candidates:
        return g

    # The most populated visible tile is the repeated seed motif.
    best_count = max(count for count, _ in candidates)
    motifs = [tile for count, tile in candidates if count == best_count]
    from collections import Counter
    motif = [list(row) for row, _ in Counter(motifs).most_common(1)[0][0]]

    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    for i, r0 in enumerate(row_origins):
        for j, c0 in enumerate(col_origins):
            if motif[i][j] != 2:
                continue
            # Recreate this tile from the seed pattern; the divider may have hidden it.
            for rr in range(d):
                for cc in range(d):
                    out[r0 + rr][c0 + cc] = motif[rr][cc]
            out[r0 + i][c0 + j] = 8
    return out
