    # Horizontal panels can have different horizontal phase, so anchor columns per panel.
    def column_anchor(c):
        if horizontal:
            side = 0 if c < band[0] else 1
            panel_cols = [x for rr, x in origins if (rr < band[0]) == (side == 0)]
            return min(panel_cols) if panel_cols else c
        left = [x for rr, x in origins if x < band[0]]
        right = [x for rr, x in origins if x > band[-1]]
